// NewDo returns a new Do.
func NewDo(body Block, cond Expr) Do {
	n := rhino.NewNode(rhino.Token_DO)
	n.AddChildToBack(body.node)
	n.AddChildToBack(cond.node)
	return Do{n}
}

// AsStatement returns x as a Statement.
func (x Do) AsStatement() Statement { return Statement{x.node} }

// AsLoop returns x as a Loop.
func (x Do) AsLoop() Loop { return Loop{x.node} }

// AsExportBody returns x as an ExportBody.
func (x Do) AsExportBody() ExportBody { return ExportBody{x.node} }

// AsScriptItem returns x as a ScriptItem.
func (x Do) AsScriptItem() ScriptItem { return ScriptItem{x.node} }

