// Grammar: Switch = SWITCH  discriminant:Expr body:SwitchBody
type Switch struct{ node rhino.Node }

// AsSwitch returns n as a Switch; ok is false if n is not one (or is the nil node).
func AsSwitch(n rhino.Node) (x Switch, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_SWITCH {
		return Switch{}, false
	}
	return Switch{n}, true
}

// Node returns x as a rhino.Node.
func (x Switch) Node() rhino.Node { return x.node }

// Discriminant returns the discriminant of x.
func (x Switch) Discriminant() Expr { return Expr{x.node.GetFirstChild()} }

// SetDiscriminant replaces the discriminant of x with v (which must not be in a tree).
func (x Switch) SetDiscriminant(v Expr) { x.node.GetFirstChild().ReplaceWith(v.node) }

// Body returns the body of x.
func (x Switch) Body() SwitchBody { return SwitchBody{x.node.GetSecondChild()} }

// SetBody replaces the body of x with v (which must not be in a tree).
func (x Switch) SetBody(v SwitchBody) { x.node.GetSecondChild().ReplaceWith(v.node) }

// NewSwitch returns a new Switch.
func NewSwitch(discriminant Expr, body SwitchBody) Switch {
	n := rhino.NewNode(rhino.Token_SWITCH)
	n.AddChildToBack(discriminant.node)
	n.AddChildToBack(body.node)
	return Switch{n}
}

// AsStatement returns x as a Statement.
func (x Switch) AsStatement() Statement { return Statement{x.node} }

// AsExportBody returns x as an ExportBody.
func (x Switch) AsExportBody() ExportBody { return ExportBody{x.node} }

// AsScriptItem returns x as a ScriptItem.
