// SwitchBody holds the cases of a switch.
//
// Grammar: SwitchBody = SWITCH_BODY  cases:SwitchCase*
type SwitchBody struct{ node rhino.Node }

// AsSwitchBody returns n as a SwitchBody; ok is false if n is not one (or is the nil node).
func AsSwitchBody(n rhino.Node) (x SwitchBody, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_SWITCH_BODY {
		return SwitchBody{}, false
	}
	return SwitchBody{n}, true
}

// Node returns x as a rhino.Node.
func (x SwitchBody) Node() rhino.Node { return x.node }

// Cases iterates over the cases of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x SwitchBody) Cases() iter.Seq[SwitchCase] {
	return func(yield func(SwitchCase) bool) {
		for c := x.node.GetFirstChild(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(SwitchCase{c}) {
				return
			}
		}
	}
}

// FirstCase returns the first of the cases of x; ok is false if there is none.
func (x SwitchBody) FirstCase() (v SwitchCase, ok bool) {
	c := x.node.GetFirstChild()
	return SwitchCase{c}, c != rhino.NilNode
}

// LastCase returns the last of the cases of x; ok is false if there is none.
func (x SwitchBody) LastCase() (v SwitchCase, ok bool) {
	c := x.node.GetLastChild()
	return SwitchCase{c}, c != rhino.NilNode
}

// HasCases reports whether x has any cases.
func (x SwitchBody) HasCases() bool { return x.node.GetFirstChild() != rhino.NilNode }

// AppendCase adds v (which must not be in a tree) after the cases of x.
func (x SwitchBody) AppendCase(v SwitchCase) { x.node.AddChildToBack(v.node) }

// PrependCase adds v (which must not be in a tree) before the cases of x.
func (x SwitchBody) PrependCase(v SwitchCase) { x.node.AddChildToFront(v.node) }

// NewSwitchBody returns a new SwitchBody.
func NewSwitchBody(cases ...SwitchCase) SwitchBody {
	n := rhino.NewNode(rhino.Token_SWITCH_BODY)
	for _, v := range cases {
		n.AddChildToBack(v.node)
	}
	return SwitchBody{n}
}

