// Try is try body catch finally (with a catch, a finally, or both).
//
// Grammar: Try = TRY  body:Block _catches:TryCatches finally:Block?
type Try struct{ node rhino.Node }

// AsTry returns n as a Try; ok is false if n is not one (or is the nil node).
func AsTry(n rhino.Node) (x Try, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_TRY {
		return Try{}, false
	}
	return Try{n}, true
}

// Node returns x as a rhino.Node.
func (x Try) Node() rhino.Node { return x.node }

// Body returns the body of x.
func (x Try) Body() Block { return Block{x.node.GetFirstChild()} }

// SetBody replaces the body of x with v (which must not be in a tree).
func (x Try) SetBody(v Block) { x.node.GetFirstChild().ReplaceWith(v.node) }

// catches returns the catches of x.
func (x Try) catches() TryCatches { return TryCatches{x.node.GetSecondChild()} }

// Finally returns the finally of x; ok is false if x has none.
func (x Try) Finally() (v Block, ok bool) {
	c := x.node.GetChildAtIndex(2)
	return Block{c}, c != rhino.NilNode
}

// SetFinally sets the finally of x to v (which must not be in a tree).
func (x Try) SetFinally(v Block) {
	if c := x.node.GetChildAtIndex(2); c != rhino.NilNode {
		c.ReplaceWith(v.node)
	} else {
		x.node.AddChildToBack(v.node)
	}
}

// RemoveFinally detaches the finally of x, if it has one.
func (x Try) RemoveFinally() {
	if c := x.node.GetChildAtIndex(2); c != rhino.NilNode {
		c.Detach()
	}
}

// AsStatement returns x as a Statement.
func (x Try) AsStatement() Statement { return Statement{x.node} }

// AsExportBody returns x as an ExportBody.
func (x Try) AsExportBody() ExportBody { return ExportBody{x.node} }

