// NameDeclaration is var, let or const, with one or more declarators.
//
// Grammar: NameDeclaration = VAR | LET | CONST  declarators:Declarator*
type NameDeclaration struct{ node rhino.Node }

// AsNameDeclaration returns n as a NameDeclaration; ok is false if n is not one (or is the nil node).
func AsNameDeclaration(n rhino.Node) (x NameDeclaration, ok bool) {
	if n == rhino.NilNode {
		return NameDeclaration{}, false
	}
	switch n.GetToken() {
	case rhino.Token_VAR, rhino.Token_LET, rhino.Token_CONST:
		return NameDeclaration{n}, true
	}
	return NameDeclaration{}, false
}

// Node returns x as a rhino.Node.
func (x NameDeclaration) Node() rhino.Node { return x.node }

// Token returns which of VAR, LET, CONST x is.
func (x NameDeclaration) Token() rhino.Token { return x.node.GetToken() }

// Declarators iterates over the declarators of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x NameDeclaration) Declarators() iter.Seq[Declarator] {
	return func(yield func(Declarator) bool) {
		for c := x.node.GetFirstChild(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(Declarator{c}) {
				return
			}
		}
	}
}

// FirstDeclarator returns the first of the declarators of x; ok is false if there is none.
func (x NameDeclaration) FirstDeclarator() (v Declarator, ok bool) {
	c := x.node.GetFirstChild()
	return Declarator{c}, c != rhino.NilNode
}

// LastDeclarator returns the last of the declarators of x; ok is false if there is none.
func (x NameDeclaration) LastDeclarator() (v Declarator, ok bool) {
	c := x.node.GetLastChild()
	return Declarator{c}, c != rhino.NilNode
}

// HasDeclarators reports whether x has any declarators.
func (x NameDeclaration) HasDeclarators() bool { return x.node.GetFirstChild() != rhino.NilNode }

// AppendDeclarator adds v (which must not be in a tree) after the declarators of x.
func (x NameDeclaration) AppendDeclarator(v Declarator) { x.node.AddChildToBack(v.node) }

// PrependDeclarator adds v (which must not be in a tree) before the declarators of x.
func (x NameDeclaration) PrependDeclarator(v Declarator) { x.node.AddChildToFront(v.node) }

// NewNameDeclaration returns a new NameDeclaration.
func NewNameDeclaration(token rhino.Token, declarators ...Declarator) NameDeclaration {
	switch token {
	case rhino.Token_VAR, rhino.Token_LET, rhino.Token_CONST:
	default:
		panic("ast.NewNameDeclaration: " + token.String() + " is not a NameDeclaration")
	}
	n := rhino.NewNode(token)
	for _, v := range declarators {
		n.AddChildToBack(v.node)
	}
	return NameDeclaration{n}
}

// AsStatement returns x as a Statement.
func (x NameDeclaration) AsStatement() Statement { return Statement{x.node} }

// AsForInit returns x as a ForInit.
func (x NameDeclaration) AsForInit() ForInit { return ForInit{x.node} }

// AsForTarget returns x as a ForTarget.
func (x NameDeclaration) AsForTarget() ForTarget { return ForTarget{x.node} }

// AsExportBody returns x as an ExportBody.
func (x NameDeclaration) AsExportBody() ExportBody { return ExportBody{x.node} }

// AsScriptItem returns x as a ScriptItem.
func (x NameDeclaration) AsScriptItem() ScriptItem { return ScriptItem{x.node} }

