// Node returns x as a rhino.Node.
func (x Break) Node() rhino.Node { return x.node }

// Label returns the label of x; ok is false if x has none.
func (x Break) Label() (v LabelName, ok bool) {
	c := x.node.GetFirstChild()
	return LabelName{c}, c != rhino.NilNode
}

// SetLabel sets the label of x to v (which must not be in a tree).
func (x Break) SetLabel(v LabelName) {
	if c := x.node.GetFirstChild(); c != rhino.NilNode {
		c.ReplaceWith(v.node)
	} else {
		x.node.AddChildToBack(v.node)
	}
}

// RemoveLabel detaches the label of x, if it has one.
func (x Break) RemoveLabel() {
	if c := x.node.GetFirstChild(); c != rhino.NilNode {
		c.Detach()
	}
}

// NewBreak returns a new Break.
func NewBreak() Break {
	n := rhino.NewNode(rhino.Token_BREAK)
	return Break{n}
}

