// SetParams replaces the params of x with v (which must not be in a tree).
func (x Function) SetParams(v ParamList) { x.node.GetSecondChild().ReplaceWith(v.node) }

// Body returns the body of x.
func (x Function) Body() FunctionBody { return FunctionBody{x.node.GetLastChild()} }

// SetBody replaces the body of x with v (which must not be in a tree).
func (x Function) SetBody(v FunctionBody) { x.node.GetLastChild().ReplaceWith(v.node) }

