// ParamList holds the parameters of a function.
//
// Grammar: ParamList = PARAM_LIST  params:Param*
type ParamList struct{ node rhino.Node }

// AsParamList returns n as a ParamList; ok is false if n is not one (or is the nil node).
func AsParamList(n rhino.Node) (x ParamList, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_PARAM_LIST {
		return ParamList{}, false
	}
	return ParamList{n}, true
}

// Node returns x as a rhino.Node.
func (x ParamList) Node() rhino.Node { return x.node }

// Params iterates over the params of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x ParamList) Params() iter.Seq[Param] {
	return func(yield func(Param) bool) {
		for c := x.node.GetFirstChild(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(Param{c}) {
				return
			}
		}
	}
}

// FirstParam returns the first of the params of x; ok is false if there is none.
func (x ParamList) FirstParam() (v Param, ok bool) {
	c := x.node.GetFirstChild()
	return Param{c}, c != rhino.NilNode
}

// LastParam returns the last of the params of x; ok is false if there is none.
func (x ParamList) LastParam() (v Param, ok bool) {
	c := x.node.GetLastChild()
	return Param{c}, c != rhino.NilNode
}

// HasParams reports whether x has any params.
func (x ParamList) HasParams() bool { return x.node.GetFirstChild() != rhino.NilNode }

// AppendParam adds v (which must not be in a tree) after the params of x.
func (x ParamList) AppendParam(v Param) { x.node.AddChildToBack(v.node) }

// PrependParam adds v (which must not be in a tree) before the params of x.
func (x ParamList) PrependParam(v Param) { x.node.AddChildToFront(v.node) }

// NewParamList returns a new ParamList.
func NewParamList(params ...Param) ParamList {
	n := rhino.NewNode(rhino.Token_PARAM_LIST)
	for _, v := range params {
		n.AddChildToBack(v.node)
	}
	return ParamList{n}
}

