// ClassBody holds the members of a class.
//
// Grammar: ClassBody = CLASS_MEMBERS  members:ClassMember*
type ClassBody struct{ node rhino.Node }

// AsClassBody returns n as a ClassBody; ok is false if n is not one (or is the nil node).
func AsClassBody(n rhino.Node) (x ClassBody, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_CLASS_MEMBERS {
		return ClassBody{}, false
	}
	return ClassBody{n}, true
}

// Node returns x as a rhino.Node.
func (x ClassBody) Node() rhino.Node { return x.node }

// Members iterates over the members of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x ClassBody) Members() iter.Seq[ClassMember] {
	return func(yield func(ClassMember) bool) {
		for c := x.node.GetFirstChild(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(ClassMember{c}) {
				return
			}
		}
	}
}

// FirstMember returns the first of the members of x; ok is false if there is none.
func (x ClassBody) FirstMember() (v ClassMember, ok bool) {
	c := x.node.GetFirstChild()
	return ClassMember{c}, c != rhino.NilNode
}

// LastMember returns the last of the members of x; ok is false if there is none.
func (x ClassBody) LastMember() (v ClassMember, ok bool) {
	c := x.node.GetLastChild()
	return ClassMember{c}, c != rhino.NilNode
}

// HasMembers reports whether x has any members.
func (x ClassBody) HasMembers() bool { return x.node.GetFirstChild() != rhino.NilNode }

// AppendMember adds v (which must not be in a tree) after the members of x.
func (x ClassBody) AppendMember(v ClassMember) { x.node.AddChildToBack(v.node) }

// PrependMember adds v (which must not be in a tree) before the members of x.
func (x ClassBody) PrependMember(v ClassMember) { x.node.AddChildToFront(v.node) }

// NewClassBody returns a new ClassBody.
func NewClassBody(members ...ClassMember) ClassBody {
	n := rhino.NewNode(rhino.Token_CLASS_MEMBERS)
	for _, v := range members {
		n.AddChildToBack(v.node)
	}
	return ClassBody{n}
}

