// RegExp is /pattern/flags.
//
// Grammar: RegExp = REGEXP  pattern:StringLit flags:StringLit?
type RegExp struct{ node rhino.Node }

// AsRegExp returns n as a RegExp; ok is false if n is not one (or is the nil node).
func AsRegExp(n rhino.Node) (x RegExp, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_REGEXP {
		return RegExp{}, false
	}
	return RegExp{n}, true
}

// Node returns x as a rhino.Node.
func (x RegExp) Node() rhino.Node { return x.node }

// Pattern returns the pattern of x.
func (x RegExp) Pattern() StringLit { return StringLit{x.node.GetFirstChild()} }

// SetPattern replaces the pattern of x with v (which must not be in a tree).
func (x RegExp) SetPattern(v StringLit) { x.node.GetFirstChild().ReplaceWith(v.node) }

// Flags returns the flags of x; ok is false if x has none.
func (x RegExp) Flags() (v StringLit, ok bool) {
	c := x.node.GetSecondChild()
	return StringLit{c}, c != rhino.NilNode
}

// SetFlags sets the flags of x to v (which must not be in a tree).
func (x RegExp) SetFlags(v StringLit) {
	if c := x.node.GetSecondChild(); c != rhino.NilNode {
		c.ReplaceWith(v.node)
	} else {
		x.node.AddChildToBack(v.node)
	}
}

// RemoveFlags detaches the flags of x, if it has one.
func (x RegExp) RemoveFlags() {
	if c := x.node.GetSecondChild(); c != rhino.NilNode {
		c.Detach()
	}
}

// NewRegExp returns a new RegExp.
func NewRegExp(pattern StringLit) RegExp {
	n := rhino.NewNode(rhino.Token_REGEXP)
	n.AddChildToBack(pattern.node)
	return RegExp{n}
}

