// TemplateLit is a template literal: `parts`.
//
// Grammar: TemplateLit = TEMPLATELIT  parts:TemplatePart*
type TemplateLit struct{ node rhino.Node }

// AsTemplateLit returns n as a TemplateLit; ok is false if n is not one (or is the nil node).
func AsTemplateLit(n rhino.Node) (x TemplateLit, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_TEMPLATELIT {
		return TemplateLit{}, false
	}
	return TemplateLit{n}, true
}

// Node returns x as a rhino.Node.
func (x TemplateLit) Node() rhino.Node { return x.node }

// Parts iterates over the parts of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x TemplateLit) Parts() iter.Seq[TemplatePart] {
	return func(yield func(TemplatePart) bool) {
		for c := x.node.GetFirstChild(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(TemplatePart{c}) {
				return
			}
		}
	}
}

// FirstPart returns the first of the parts of x; ok is false if there is none.
func (x TemplateLit) FirstPart() (v TemplatePart, ok bool) {
	c := x.node.GetFirstChild()
	return TemplatePart{c}, c != rhino.NilNode
}

// LastPart returns the last of the parts of x; ok is false if there is none.
func (x TemplateLit) LastPart() (v TemplatePart, ok bool) {
	c := x.node.GetLastChild()
	return TemplatePart{c}, c != rhino.NilNode
}

// HasParts reports whether x has any parts.
func (x TemplateLit) HasParts() bool { return x.node.GetFirstChild() != rhino.NilNode }

// AppendPart adds v (which must not be in a tree) after the parts of x.
func (x TemplateLit) AppendPart(v TemplatePart) { x.node.AddChildToBack(v.node) }

// PrependPart adds v (which must not be in a tree) before the parts of x.
func (x TemplateLit) PrependPart(v TemplatePart) { x.node.AddChildToFront(v.node) }

// NewTemplateLit returns a new TemplateLit.
func NewTemplateLit(parts ...TemplatePart) TemplateLit {
	n := rhino.NewNode(rhino.Token_TEMPLATELIT)
	for _, v := range parts {
		n.AddChildToBack(v.node)
	}
	return TemplateLit{n}
}

