// Call is callee(args).
//
// Grammar: Call = CALL  callee:Expr args:Arg*
type Call struct{ node rhino.Node }

// AsCall returns n as a Call; ok is false if n is not one (or is the nil node).
func AsCall(n rhino.Node) (x Call, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_CALL {
		return Call{}, false
	}
	return Call{n}, true
}

// Node returns x as a rhino.Node.
func (x Call) Node() rhino.Node { return x.node }

// Callee returns the callee of x.
func (x Call) Callee() Expr { return Expr{x.node.GetFirstChild()} }

// SetCallee replaces the callee of x with v (which must not be in a tree).
func (x Call) SetCallee(v Expr) { x.node.GetFirstChild().ReplaceWith(v.node) }

// Args iterates over the args of x. Like a for loop over GetNext, it reads the next
// element after the loop body ran: a body that moves the current element elsewhere
// ends the loop early.
func (x Call) Args() iter.Seq[Arg] {
	return func(yield func(Arg) bool) {
		for c := x.node.GetFirstChild().GetNext(); c != rhino.NilNode; c = c.GetNext() {
			if !yield(Arg{c}) {
				return
			}
		}
	}
}

// FirstArg returns the first of the args of x; ok is false if there is none.
func (x Call) FirstArg() (v Arg, ok bool) {
	c := x.node.GetFirstChild().GetNext()
	return Arg{c}, c != rhino.NilNode
}

// LastArg returns the last of the args of x; ok is false if there is none.
func (x Call) LastArg() (v Arg, ok bool) {
	if x.node.GetFirstChild().GetNext() == rhino.NilNode {
		return Arg{}, false
	}
	c := x.node.GetLastChild()
	return Arg{c}, c != rhino.NilNode
}

// HasArgs reports whether x has any args.
func (x Call) HasArgs() bool { return x.node.GetFirstChild().GetNext() != rhino.NilNode }

// AppendArg adds v (which must not be in a tree) after the args of x.
func (x Call) AppendArg(v Arg) { x.node.AddChildToBack(v.node) }

// NewCall returns a new Call.
func NewCall(callee Expr, args ...Arg) Call {
	n := rhino.NewNode(rhino.Token_CALL)
	n.AddChildToBack(callee.node)
	for _, v := range args {
		n.AddChildToBack(v.node)
	}
	return Call{n}
}

// AsExpr returns x as an Expr.
func (x Call) AsExpr() Expr { return Expr{x.node} }

// AsArg returns x as an Arg.
func (x Call) AsArg() Arg { return Arg{x.node} }

