func (x Call) AsArrayElem() ArrayElem { return ArrayElem{x.node} }

// AsPropValue returns x as a PropValue.
func (x Call) AsPropValue() PropValue { return PropValue{x.node} }

// AsForInit returns x as a ForInit.
func (x Call) AsForInit() ForInit { return ForInit{x.node} }

// AsFunctionBody returns x as a FunctionBody.
func (x Call) AsFunctionBody() FunctionBody { return FunctionBody{x.node} }

// AsExportBody returns x as an ExportBody.
func (x Call) AsExportBody() ExportBody { return ExportBody{x.node} }

