// Yield is yield value.
//
// Grammar: Yield = YIELD  value:Expr?
type Yield struct{ node rhino.Node }

// AsYield returns n as a Yield; ok is false if n is not one (or is the nil node).
func AsYield(n rhino.Node) (x Yield, ok bool) {
	if n == rhino.NilNode || n.GetToken() != rhino.Token_YIELD {
		return Yield{}, false
	}
	return Yield{n}, true
}

// Node returns x as a rhino.Node.
func (x Yield) Node() rhino.Node { return x.node }

// Value returns the value of x; ok is false if x has none.
func (x Yield) Value() (v Expr, ok bool) {
	c := x.node.GetFirstChild()
	return Expr{c}, c != rhino.NilNode
}

// SetValue sets the value of x to v (which must not be in a tree).
func (x Yield) SetValue(v Expr) {
	if c := x.node.GetFirstChild(); c != rhino.NilNode {
		c.ReplaceWith(v.node)
	} else {
		x.node.AddChildToBack(v.node)
	}
}

// RemoveValue detaches the value of x, if it has one.
func (x Yield) RemoveValue() {
	if c := x.node.GetFirstChild(); c != rhino.NilNode {
		c.Detach()
	}
}

// NewYield returns a new Yield.
func NewYield() Yield {
	n := rhino.NewNode(rhino.Token_YIELD)
	return Yield{n}
}

