// Statement is any statement.
//
// Grammar: Statement = Label | Block | Function | With | For | ForIn | ForOf | ForAwaitOf | While | Do | Switch | If | NameDeclaration | ExprStmt | Return | Throw | Try | Break | Continue | Empty | Debugger | Class | Import | Export | Interface | Enum | TypeAlias | Declare | Namespace
type Statement struct{ node rhino.Node }

// AsStatement returns n as a Statement; ok is false if n is not one (or is the nil node).
func AsStatement(n rhino.Node) (x Statement, ok bool) {
	if n == rhino.NilNode {
		return Statement{}, false
	}
	switch n.GetToken() {
	case rhino.Token_BLOCK, rhino.Token_LABEL, rhino.Token_IF, rhino.Token_FOR, rhino.Token_FOR_IN, rhino.Token_FOR_OF, rhino.Token_FOR_AWAIT_OF, rhino.Token_WHILE, rhino.Token_DO, rhino.Token_WITH, rhino.Token_SWITCH, rhino.Token_TRY, rhino.Token_VAR, rhino.Token_LET, rhino.Token_CONST, rhino.Token_EXPR_RESULT, rhino.Token_RETURN, rhino.Token_THROW, rhino.Token_BREAK, rhino.Token_CONTINUE, rhino.Token_EMPTY, rhino.Token_DEBUGGER, rhino.Token_FUNCTION, rhino.Token_CLASS, rhino.Token_IMPORT, rhino.Token_EXPORT, rhino.Token_INTERFACE, rhino.Token_ENUM, rhino.Token_TYPE_ALIAS, rhino.Token_DECLARE, rhino.Token_NAMESPACE:
		return Statement{n}, true
	}
	return Statement{}, false
}

// Node returns x as a rhino.Node.
func (x Statement) Node() rhino.Node { return x.node }

// AsBlock returns x as a Block; ok is false if it is not one.
func (x Statement) AsBlock() (Block, bool) { return AsBlock(x.node) }

// AsLabel returns x as a Label; ok is false if it is not one.
func (x Statement) AsLabel() (Label, bool) { return AsLabel(x.node) }

// AsIf returns x as an If; ok is false if it is not one.
func (x Statement) AsIf() (If, bool) { return AsIf(x.node) }

// AsFor returns x as a For; ok is false if it is not one.
func (x Statement) AsFor() (For, bool) { return AsFor(x.node) }

// AsForIn returns x as a ForIn; ok is false if it is not one.
func (x Statement) AsForIn() (ForIn, bool) { return AsForIn(x.node) }

// AsForOf returns x as a ForOf; ok is false if it is not one.
func (x Statement) AsForOf() (ForOf, bool) { return AsForOf(x.node) }

// AsForAwaitOf returns x as a ForAwaitOf; ok is false if it is not one.
func (x Statement) AsForAwaitOf() (ForAwaitOf, bool) { return AsForAwaitOf(x.node) }

// AsWhile returns x as a While; ok is false if it is not one.
func (x Statement) AsWhile() (While, bool) { return AsWhile(x.node) }

