// Pattern is a destructuring pattern.
//
// Grammar: Pattern = ArrayPattern | ObjectPattern
type Pattern struct{ node rhino.Node }

// AsPattern returns n as a Pattern; ok is false if n is not one (or is the nil node).
func AsPattern(n rhino.Node) (x Pattern, ok bool) {
	if n == rhino.NilNode {
		return Pattern{}, false
	}
	switch n.GetToken() {
	case rhino.Token_ARRAY_PATTERN, rhino.Token_OBJECT_PATTERN:
		return Pattern{n}, true
	}
	return Pattern{}, false
}

// Node returns x as a rhino.Node.
func (x Pattern) Node() rhino.Node { return x.node }

// AsArrayPattern returns x as an ArrayPattern; ok is false if it is not one.
func (x Pattern) AsArrayPattern() (ArrayPattern, bool) { return AsArrayPattern(x.node) }

// AsObjectPattern returns x as an ObjectPattern; ok is false if it is not one.
func (x Pattern) AsObjectPattern() (ObjectPattern, bool) { return AsObjectPattern(x.node) }

// AsTarget returns x as a Target.
func (x Pattern) AsTarget() Target { return Target{x.node} }

// AsParam returns x as a Param.
func (x Pattern) AsParam() Param { return Param{x.node} }

// AsArrayPatternElem returns x as an ArrayPatternElem.
func (x Pattern) AsArrayPatternElem() ArrayPatternElem { return ArrayPatternElem{x.node} }

// AsPropValue returns x as a PropValue.
func (x Pattern) AsPropValue() PropValue { return PropValue{x.node} }

