// AsCatchParam returns x as a CatchParam.
func (x Pattern) AsCatchParam() CatchParam { return CatchParam{x.node} }

// Param is a function parameter.
//
// Grammar: Param = Name | ArrayPattern | ObjectPattern | DefaultValue | IterRest
type Param struct{ node rhino.Node }

// AsParam returns n as a Param; ok is false if n is not one (or is the nil node).
func AsParam(n rhino.Node) (x Param, ok bool) {
	if n == rhino.NilNode {
		return Param{}, false
	}
	switch n.GetToken() {
	case rhino.Token_DEFAULT_VALUE, rhino.Token_ITER_REST, rhino.Token_ARRAY_PATTERN, rhino.Token_OBJECT_PATTERN, rhino.Token_NAME:
		return Param{n}, true
	}
	return Param{}, false
}

