// TemplatePart is a part of a template literal.
//
// Grammar: TemplatePart = TemplateLitString | TemplateLitSub
type TemplatePart struct{ node rhino.Node }

// AsTemplatePart returns n as a TemplatePart; ok is false if n is not one (or is the nil node).
func AsTemplatePart(n rhino.Node) (x TemplatePart, ok bool) {
	if n == rhino.NilNode {
		return TemplatePart{}, false
	}
	switch n.GetToken() {
	case rhino.Token_TEMPLATELIT_STRING, rhino.Token_TEMPLATELIT_SUB:
		return TemplatePart{n}, true
	}
	return TemplatePart{}, false
}

// Node returns x as a rhino.Node.
func (x TemplatePart) Node() rhino.Node { return x.node }

// AsTemplateLitString returns x as a TemplateLitString; ok is false if it is not one.
func (x TemplatePart) AsTemplateLitString() (TemplateLitString, bool) {
	return AsTemplateLitString(x.node)
}

// AsTemplateLitSub returns x as a TemplateLitSub; ok is false if it is not one.
func (x TemplatePart) AsTemplateLitSub() (TemplateLitSub, bool) { return AsTemplateLitSub(x.node) }

// ImportBindings is what an import binds besides its default.
//
// Grammar: ImportBindings = ImportSpecs | ImportStar
type ImportBindings struct{ node rhino.Node }

// AsImportBindings returns n as an ImportBindings; ok is false if n is not one (or is the nil node).
func AsImportBindings(n rhino.Node) (x ImportBindings, ok bool) {
	if n == rhino.NilNode {
		return ImportBindings{}, false
	}
	switch n.GetToken() {
	case rhino.Token_IMPORT_SPECS, rhino.Token_IMPORT_STAR:
		return ImportBindings{n}, true
	}
	return ImportBindings{}, false
}

